package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;

/**
 * The single duplicate check for a create-owner request: it consolidates the former separate
 * telephone, email and household checks into one comparison of the whole derived
 * {@link OwnerIdentityKey identity key}
 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}).
 *
 * <p>Runs after the telephone and email have been normalized and after
 * {@link DetermineOwnerHousehold} has resolved any shared {@code householdId}, so the request's
 * key is built from the same normalized parts as each existing owner's key. A create is rejected
 * with a 409 only when the request's whole identity key equals an existing owner's — so two
 * members of the same household with different telephones (different keys) are both allowed.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
            OwnerRepository ownerRepository) throws DuplicateOwnerIdentityException {
        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(),
                householdId == null ? null : householdId.value());
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
                throw new DuplicateOwnerIdentityException(identityKey);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single derived identity of an owner used for duplicate detection.
 *
 * <p>An owner's {@code identityKey} is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is its E.164 form, the email is its lower-cased form (empty when absent or
 * blank) and the householdId is the owner's shared-household identifier (empty when the
 * owner does not share a household). Two owners are duplicates only when their whole
 * identity keys are equal — so, for example, two members of the same household (same
 * householdId) with different telephones have different keys and are both allowed.
 */
public final class OwnerIdentityKey {

    private OwnerIdentityKey() {
    }

    /**
     * Builds an identity key from its already-normalized parts.
     *
     * @param telephoneE164 the E.164 telephone (never blank for a valid owner)
     * @param email the email, or {@code null}/blank when none
     * @param householdId the shared-household id, or {@code null}/empty when none
     * @return the {@code telephone|email|householdId} identity key
     */
    public static String of(String telephoneE164, String email, String householdId) {
        String tel = telephoneE164 == null ? "" : telephoneE164;
        String mail = (email == null || email.trim().isEmpty()) ? ""
                : email.trim().toLowerCase(Locale.ROOT);
        String household = (householdId == null || householdId.isEmpty()) ? "" : householdId;
        return tel + "|" + mail + "|" + household;
    }

    /**
     * Derives the identity key of a stored owner, normalizing its telephone to E.164 and its
     * email to lower case exactly as the create pipeline normalizes an incoming request, so a
     * new owner and an existing owner are compared on the same footing.
     */
    public static String forOwner(Owner owner) {
        return of(TelephoneNormalizer.toE164(owner.getTelephone()), owner.getEmail(),
                owner.getHouseholdId());
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        // Registration must land on a business day: a supplied or defaulted weekend rolls forward
        // to Monday, and every value later derived from this date uses the adjusted value.
        owner.setRegistrationDate(BusinessDay.roll(effective));
        built.set(owner);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

public class SaveOwner {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        ownerRepository.save(owner);
    }
}

